import type { MetadataRoute } from "next";
import { LANDING_URL as LANDING } from "@/api/http";

// The landing is one page. Auction pages live on web.zotdor.uz and are listed in its own
// sitemap, generated by the API from the database (backend/seo/views.py).
export default function sitemap(): MetadataRoute.Sitemap {
  return [{ url: `${LANDING}/`, changeFrequency: "daily", priority: 1 }];
}
